function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 30000) return 'nums needs 1 to 30000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 2 || v > 100000)) return 'Each value is an integer from 2 to 100000.';
  return null;
}

