  const smallestPrime = new Array(maxValue + 1).fill(0);
  for (let p = 2; p <= maxValue; p++) {
    if (smallestPrime[p] !== 0) {
      continue;
    }
    for (let multiple = p; multiple <= maxValue; multiple += p) {
      if (smallestPrime[multiple] === 0) {
        smallestPrime[multiple] = p;
      }
    }
  }
