function gcdSort(nums) {
  const n = nums.length;
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  // Group positions whose values are linked by a chain of pairs with gcd > 1.
  const group = new Array(n).fill(-1);
  for (let s = 0; s < n; s++) {
    if (group[s] !== -1) continue;
    group[s] = s;
    const stack = [s];
    while (stack.length) {
      const u = stack.pop();
      for (let v = 0; v < n; v++) {
        if (group[v] === -1 && gcd(nums[u], nums[v]) > 1) { group[v] = s; stack.push(v); }
      }
    }
  }
  // A group can arrange its values freely over its own positions; place them in increasing order.
  const result = new Array(n);
  for (let s = 0; s < n; s++) {
    if (group[s] !== s) continue;
    const positions = [];
    for (let i = 0; i < n; i++) if (group[i] === s) positions.push(i);
    const values = positions.map(i => nums[i]).sort((a, b) => a - b);
    positions.forEach((pos, k) => { result[pos] = values[k]; });
  }
  for (let i = 1; i < n; i++) if (result[i - 1] > result[i]) return false;
  return true;
}

