function generate(rand, size) {
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 100000 : (rand() < 0.5 ? 30 : 100);
  const nums = Array.from({ length: n }, () => 2 + Math.floor(rand() * (top - 1)));
  if (rand() < 0.5) {
    // Start sorted and make only allowed swaps, so the array is known to be sortable.
    nums.sort((a, b) => a - b);
    for (let step = 0; step < 4 * n; step++) {
      const i = Math.floor(rand() * n), j = Math.floor(rand() * n);
      if (gcd(nums[i], nums[j]) > 1) [nums[i], nums[j]] = [nums[j], nums[i]];
    }
    // Sometimes add one unrestricted swap, which may or may not break sortability.
    if (rand() < 0.4) {
      const i = Math.floor(rand() * n), j = Math.floor(rand() * n);
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  return [nums];
}
